<script setup>
import {ref,onMounted} from 'vue';import AppShell from '../components/AppShell.vue';import {supabase} from '../services/supabase';import {RouterLink} from 'vue-router';const rows=ref([]),loading=ref(true);onMounted(async()=>{const {data:{user}}=await supabase.auth.getUser();const {data}=await supabase.from('applications').select('*, job:jobs(id,title,location,job_type,employer:profiles!jobs_employer_id_fkey(company_name,full_name))').eq('student_id',user.id).order('created_at',{ascending:false});rows.value=data||[];loading.value=false});async function withdraw(a){if(!confirm('Withdraw this application?'))return;const {error}=await supabase.from('applications').update({status:'withdrawn'}).eq('id',a.id);if(!error)a.status='withdrawn'}
</script>
<template><AppShell title="My applications" subtitle="Follow every opportunity"><template #default><span class="eyebrow">STUDENT WORKSPACE</span><h1 class="page-title">My applications</h1><p class="page-subtitle">See where things stand and keep track of your opportunities.</p><div v-if="loading" class="empty">Loading applications…</div><div v-else-if="rows.length" class="table-wrap" style="margin-top:22px"><table><thead><tr><th>Job</th><th>Employer</th><th>Applied</th><th>Status</th><th>Action</th></tr></thead><tbody><tr v-for="a in rows" :key="a.id"><td><RouterLink :to="`/jobs/${a.job?.id}`"><b>{{a.job?.title||'Job unavailable'}}</b></RouterLink><div class="muted">{{a.job?.location}}</div></td><td>{{a.job?.employer?.company_name||a.job?.employer?.full_name||'Employer'}}</td><td>{{new Date(a.created_at).toLocaleDateString('en-ZA')}}</td><td><span class="badge" :class="a.status==='accepted'?'green':a.status==='rejected'?'':'gold'">{{a.status}}</span></td><td><button v-if="!['withdrawn','accepted','rejected'].includes(a.status)" class="btn btn-outline" style="padding:6px 9px;font-size:11px" @click="withdraw(a)">Withdraw</button></td></tr></tbody></table></div><div v-else class="empty"><h3>No applications yet</h3><p>Find a role that fits and send your first application.</p><RouterLink to="/jobs" class="btn btn-primary">Explore jobs</RouterLink></div></template></AppShell></template>
